"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["26887"],{70783(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.aplicacao_de_modelo.fase_do_documento_inexistente","status":422,"titulo":"O modelo exige documento em fase que o cronograma do processo n\xe3o tem"},"descricao":{"codigo":"uniplus.selecao.aplicacao_de_modelo.fase_do_documento_inexistente","requisitos":["UNI-REQ-0170"],"oQueAconteceu":["Alguns modelos de formul\xe1rio trazem um conjunto padr\xe3o de documentos exigidos,\\ncada um ligado a uma fase, que \xe9 copiado para o processo junto com o formul\xe1rio.\\nAo copiar, a fase de cada documento \xe9 procurada pelo c\xf3digo no cronograma do\\nprocesso, e o documento do modelo aponta uma fase que o cronograma n\xe3o tem. \xc9 o\\ncaso do conjunto do atendimento especializado, que exige a fase de inscri\xe7\xe3o no\\ncronograma do processo (UNI-REQ-0170). A recusa traz a posi\xe7\xe3o\\n`documentosExigidos[n].faseCodigo` do documento no modelo e, na mensagem, o tipo\\nde documento e o c\xf3digo da fase.","Esta \xe9 a \xfaltima etapa da aplica\xe7\xe3o: ela s\xf3 roda depois de o formul\xe1rio, os itens,\\nos termos e as deriva\xe7\xf5es do modelo terem sido aceitos, e uma recusa aqui desfaz a\\naplica\xe7\xe3o inteira, sem alterar o processo. Para cada documento do modelo a fase e\\no tipo de documento s\xe3o conferidos separadamente, por isso a recusa de\\n[`tipo_de_documento_inexistente`](/erros/uniplus.selecao.aplicacao_de_modelo.tipo_de_documento_inexistente)\\npode vir junto na mesma resposta."],"comoResolver":["Defina o cronograma do processo com a fase citada na mensagem (defini\xe7\xe3o do\\ncronograma de fases) e reaplique o modelo. Se o processo n\xe3o ter\xe1 essa fase,\\nescolha outro modelo, cujo conjunto de documentos n\xe3o dependa dela."],"ondeAparece":["Aplica\xe7\xe3o de modelo de formul\xe1rio"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Aplicacao de modelo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);